#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Overlay binary Enemy keyCosts onto vault-v29.generated.ts (in place).
 *
 *   node scripts/apply-vault-v29-enemy-overlay.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..')
const VAULT_TS = path.join(PACKAGE_ROOT, 'src', 'data', 'generated', 'vault-v29.generated.ts')
const SRC_JSON = path.join(REPO_ROOT, 'extraction-core', 'dumps', 'v29.0.0-arm64', 'vault-enemy-keycosts-native.json')

const ENEMY_BY_TYPE = {
  0: 'Basic',
  1: 'Fast',
  2: 'Tank',
  3: 'Ranged',
  4: 'Boss',
  5: 'Protector',
  6: 'Vampire',
  7: 'Scatter',
  9: 'Ray',
  10: 'Saboteur',
  11: 'Commander',
  12: 'Overcharge',
}

const payload = JSON.parse(fs.readFileSync(SRC_JSON, 'utf8'))
const byEnemyStat = {}

for (const group of payload.enemyGroups ?? []) {
  for (const up of group.upgrades ?? []) {
    const enemy = ENEMY_BY_TYPE[up.enemyType]
    const slot = Math.floor((up.vaultId % 100) / 10)
    const costs = up.keyCosts ?? []
    if (enemy == null || !costs.length) continue
    byEnemyStat[`${enemy}|${slot}`] = costs
  }
}

const statSlot = stat => {
  const s = stat.toLowerCase()
  if (s.includes('attack')) return 0
  if (s.includes('health')) return 1
  return 2
}

let src = fs.readFileSync(VAULT_TS, 'utf8')
const enemyBlockRe = /export const VAULT_V29_ENEMY:[\s\S]*?= (\{[\s\S]*?\}) as const/
const match = src.match(enemyBlockRe)
if (!match) {
  console.error('Could not find VAULT_V29_ENEMY block')
  process.exit(1)
}

const enemyTree = JSON.parse(match[1])
let overlaid = 0
const missing = []

for (const row of enemyTree.upgrades) {
  const key = `${row.enemy}|${statSlot(row.stat)}`
  const costs = byEnemyStat[key]
  if (!costs) {
    missing.push(`${key} (${row.stat})`)
    continue
  }
  row.levelCosts = [...costs]
  overlaid++
}

if (missing.length) {
  console.error('No binary row for:', missing)
  process.exit(1)
}

const replaced = `export const VAULT_V29_ENEMY: {
  readonly categories: readonly VaultV29Category[]
  readonly upgrades: readonly VaultV29EnemyUpgrade[]
} = ${JSON.stringify(enemyTree, null, 2)} as const`

src = src.replace(enemyBlockRe, replaced)

if (!src.includes('vault-v29-binary-enemy-keycosts.generated.ts')) {
  src = src.replace(
    'Enemy tree is workbook-only',
    'Enemy tree levelCosts overlaid from vault-v29-binary-enemy-keycosts.generated.ts (SO extract); workbook floats were placeholders',
  )
  src = src.replace(
    /export const VAULT_V29_PROVENANCE =\n {2}'developer-supplied workbook[^']*'/,
    `export const VAULT_V29_PROVENANCE =
  'developer-supplied workbook, 2026-08-21; Harmony + Power T1 + Enemy keyCosts overlaid from v29 binary/SO extract (vault-v29-binary-keycosts.generated.ts, vault-v29-binary-enemy-keycosts.generated.ts) 2026-08-27 — Power tier 1×/2×/4× key multipliers not binary-confirmed; Preset nodes SO-backed'`,
  )
}

fs.writeFileSync(VAULT_TS, src, 'utf8')
console.log(`overlaid ${overlaid} enemy rows in ${path.relative(PACKAGE_ROOT, VAULT_TS)}`)
